/** `bulk-uploads` endpoints. */
export class BulkUploadsApi {
  private readonly c: Transport;

  constructor(transport: Transport) {
    this.c = transport;
  }

  /**
   * Upload File.
   *
   * POST /api/v1/bulk-uploads
   *
   * Uploads a file to import in the background. Poll `status_url` for progress. A file
   * that can't be read at all comes back `rejected`, with the reason in `error`.
   */
  uploadFile(form: { create_missing_accounts?: boolean; file: Blob; format: string; kind: BulkUploadKind }): Promise<BulkUploadAccepted> {
    return this.c.call<BulkUploadAccepted>("POST", `/api/v1/bulk-uploads`, { multipart: form });
  }

  /**
   * List Import Formats.
   *
   * GET /api/v1/bulk-uploads/formats
   *
   * The import formats this organization can send to `POST /api/v1/bulk-uploads`: the
   * built-in ones and any a plugin provides that an admin has turned on, limited to the
   * kinds the caller may upload.
   */
  listImportFormats(): Promise<Array<ImportFormatRead>> {
    return this.c.call<Array<ImportFormatRead>>("GET", `/api/v1/bulk-uploads/formats`, {  });
  }

  /**
   * Get Bulk Upload.
   *
   * GET /api/v1/bulk-uploads/{upload_id}
   *
   * Where the import is: `queued`, `processing` (`processed_rows` of `total_rows`),
   * `completed`, `rejected` (nothing imported; see `error`) or `failed`.
   */
  getBulkUpload(uploadId: string): Promise<BulkUploadRead> {
    return this.c.call<BulkUploadRead>("GET", `/api/v1/bulk-uploads/${encodeURIComponent(String(uploadId))}`, {  });
  }

  /**
   * Get Bulk Upload Results.
   *
   * GET /api/v1/bulk-uploads/{upload_id}/results
   *
   * Each imported row's outcome, in file order, paged. `index` is the row's position in
   * the request (0-based) or file.
   */
  getBulkUploadResults(uploadId: string, query: { failures_only?: boolean; limit?: number; offset?: number } = {}): Promise<Array<BulkUploadRowRead>> {
    return this.c.call<Array<BulkUploadRowRead>>("GET", `/api/v1/bulk-uploads/${encodeURIComponent(String(uploadId))}/results`, { query });
  }

  /**
   * Every row of getBulkUploadResults, following each page's `Link: rel="next"`.
   *
   * GET /api/v1/bulk-uploads/{upload_id}/results
   */
  iterGetBulkUploadResults(uploadId: string, query: { failures_only?: boolean; limit?: number } = {}): AsyncIterable<BulkUploadRowRead> {
    return this.c.paginate<BulkUploadRowRead>("GET", `/api/v1/bulk-uploads/${encodeURIComponent(String(uploadId))}/results`, { query });
  }
}

